// lib/schemas.js
import { z } from 'zod';

export const postSchema = z.object({
  title: z.string().min(1, 'Title is required').max(100),
  content: z.string().min(10, 'Content must be at least 10 characters'),
});

// app/actions.js
'use server';
import { prisma } from '@/lib/prisma';
import { revalidatePath } from 'next/cache';
import { postSchema } from '@/lib/schemas';

export async function createPost(prevState, formData) {
  const result = postSchema.safeParse({
    title: formData.get('title'),
    content: formData.get('content'),
  });
  if (!result.success) {
    return { errors: result.error.flatten().fieldErrors };
  }
  await prisma.post.create({ data: result.data });
  revalidatePath('/posts');
  return { success: true };
}

export async function updatePost(id, prevState, formData) {
  const result = postSchema.safeParse({
    title: formData.get('title'),
    content: formData.get('content'),
  });
  if (!result.success) {
    return { errors: result.error.flatten().fieldErrors };
  }
  await prisma.post.update({ where: { id }, data: result.data });
  revalidatePath('/posts');
  return { success: true };
}

export async function deletePost(id) {
  await prisma.post.delete({ where: { id } });
  revalidatePath('/posts');
}

// components/NewPostForm.js
'use client';
import { useFormState } from 'react-dom';
import { createPost } from '@/app/actions';

const initialState = {};
export default function NewPostForm() {
  const [state, formAction] = useFormState(createPost, initialState);
  return (
    <form action={formAction}>
      <input name="title" placeholder="Title" />
      {state?.errors?.title && <span className="error">{state.errors.title[0]}</span>}
      <textarea name="content" placeholder="Content" />
      {state?.errors?.content && <span className="error">{state.errors.content[0]}</span>}
      <button type="submit">Create</button>
      {state?.success && <p className="success">Post created!</p>}
    </form>
  );
}

// components/EditPostForm.js
'use client';
import { useFormState } from 'react-dom';
import { updatePost } from '@/app/actions';

const initialState = {};
export default function EditPostForm({ post }) {
  const updatePostWithId = updatePost.bind(null, post.id);
  const [state, formAction] = useFormState(updatePostWithId, initialState);
  return (
    <form action={formAction}>
      <input name="title" defaultValue={post.title} />
      {state?.errors?.title && <span className="error">{state.errors.title[0]}</span>}
      <textarea name="content" defaultValue={post.content} />
      {state?.errors?.content && <span className="error">{state.errors.content[0]}</span>}
      <button type="submit">Update</button>
      {state?.success && <p className="success">Post updated!</p>}
    </form>
  );
}

// components/DeleteButton.js
'use client';
import { deletePost } from '@/app/actions';

export default function DeleteButton({ postId }) {
  return (
    <button onClick={() => { if (confirm('Delete?')) deletePost(postId); }}>
      Delete
    </button>
  );
}

// app/posts/page.js
import Link from 'next/link';
import { prisma } from '@/lib/prisma';
import DeleteButton from '@/components/DeleteButton';

export default async function PostsPage() {
  const posts = await prisma.post.findMany({ orderBy: { createdAt: 'desc' } });
  return (
    <div>
      <h1>Posts</h1>
      <Link href="/posts/new">New Post</Link>
      <ul>
        {posts.map(post => (
          <li key={post.id}>
            <h2>{post.title}</h2>
            <p>{post.content}</p>
            <Link href={`/posts/${post.id}/edit`}>Edit</Link>
            <DeleteButton postId={post.id} />
          </li>
        ))}
      </ul>
    </div>
  );
}

// app/posts/new/page.js
import NewPostForm from '@/components/NewPostForm';

export default function NewPostPage() {
  return (
    <div>
      <h1>New Post</h1>
      <NewPostForm />
    </div>
  );
}

// app/posts/[id]/edit/page.js
import { prisma } from '@/lib/prisma';
import EditPostForm from '@/components/EditPostForm';
import { notFound } from 'next/navigation';

export default async function EditPostPage({ params }) {
  const post = await prisma.post.findUnique({ where: { id: Number(params.id) } });
  if (!post) notFound();
  return (
    <div>
      <h1>Edit Post</h1>
      <EditPostForm post={post} />
    </div>
  );
}
